def backfill_existing_progress(apps, schema_editor):
    """Les personnages existants ont déjà été créés ; leurs formations terminées reçoivent une inscription."""
    Character = apps.get_model('game', 'Character')
    Course = apps.get_model('game', 'Course')
    CourseEnrollment = apps.get_model('game', 'CourseEnrollment')
    Character.objects.all().update(onboarding_completed=True)
    courses = {c.key: c for c in Course.objects.all()}
    for char in Character.objects.all():
        for key in (char.completed_courses or []):
            course = courses.get(key)
            if course:
                CourseEnrollment.objects.get_or_create(
                    character=char,
                    course=course,
                    defaults={
                        'status': 'completed',
                        'validated_modules': len(course.modules or []),
                    },
                )


